import{_ as o,o as a,c as t,a2 as E}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-PPROPERTIES.md","filePath":"manual-zh/CTABLES-PPROPERTIES.md","lastUpdated":1785684581000}'),P={name:"manual-zh/CTABLES-PPROPERTIES.md"};function c(d,e,p,r,_,T){return a(),t("div",null,[...e[0]||(e[0]=[E(`<h4 id="_15-7-10-2-pproperties" tabindex="-1">15.7.10.2 PPROPERTIES <a class="header-anchor" href="#_15-7-10-2-pproperties" aria-label="Permalink to &quot;15.7.10.2 PPROPERTIES&quot;">​</a></h4><pre><code>/PPROPERTIES &amp;_postcompute_ …
    [LABEL=_string_]
    [FORMAT=[_summary_ _format_]…]
    [HIDESOURCECATS={NO _|_ YES}
</code></pre><p><code>PPROPERTIES</code> 子命令必须出现在 <code>TABLE</code> 之前，用于为之前 <code>PCOMPUTE</code> 子命令定义的一个或多个后计算设置属性。该子命令的语法以后计算列表开头，每个都以 <code>PCOMPUTE</code> 中指定的 ‘&amp;’ 为前缀。</p><p><code>PPROPERTIES</code> 上的所有设置都是可选的。使用 <code>LABEL</code> 设置后计算在表输出中显示的标签。后计算的默认标签是定义它所用的表达式。</p><p>后计算始终使用包含它的变量相同的汇总函数，但 <code>FORMAT</code> 可控制用于显示其值的格式。它接受一个汇总函数名和格式说明符的列表。</p><p>默认情况下，或使用 <code>HIDESOURCECATS=NO</code> 时，计算类别所引用的类别与其他类别一样显示。使用 <code>HIDESOURCECATS=YES</code> 可隐藏它们。</p><p>上一节提供了一个 <code>PPROPERTIES</code> 的示例。</p>`,7)])])}const R=o(P,[["render",c]]);export{S as __pageData,R as default};
